namespace FancyZonesClone.Core.Overlay;

/// <summary>
/// Inter SemiBold's digits as flattened outlines, for zone numbers. Coordinates are in cap heights with y down from the
/// cap line, so a digit is about 1 tall. Fill the contours with the nonzero winding rule. <c>InterDigits.g.cs</c> holds
/// the outlines, generated by <c>eng/generate-digit-outlines.py</c>.
/// </summary>
internal static partial class InterDigits
{
    /// <summary>The outline of <paramref name="digit"/>, from 0 to 9.</summary>
    public static DigitGlyph Glyph(int digit) => _glyphs[digit];
}
